async function getCausalStrengthEdges(req, res) {

    let opts = req.body
    // retrieve model name
    let edge_strength = {}
    let intrinsic_effects = {}
    let causal_mechanisms = {}
    let local_markov_test = {}
    let edge_dependence_test = {}
    let flow_info = runtime._.flows.getFlow(opts.activeWorkspace)
    // console.log("flow info ", flow_info)
    try {
        // match the nrid of the causal path : Typ
        if (flow_info !== null) {
            for await (let node of flow_info.nodes) {
                console.log("\n\n@getCausalStrengthEdges--------" + node.name + " - " + node.id + "-------")
                if (node.type === "causeeffect") {
                    let cause_n = node.id
                    let effect_n = node.id
                    let match = "match $cp isa causeeffect, has nrid \"" + node.id + "\";\n"
                    let query_opts = {
                        "db": "causeway-repo",
                        "query": match,
                        "query_type": "match",
                        "session_type": "DATA",
                        "transaction_type": "READ"
                    }
                    // console.log("match statement: ", match)
                    // let typedb api handle executing query
                    let query_result = await typedb.executeQuery(query_opts)
                    // console.log(query_result)
                    // get transaction type instance for access to remote concepts functionality
                    let tx = await typedb.get_transaction(query_opts)
                    // // iterate through results; should be of length 1 
                    if (typeof tx !== 'string') {
                        // console.log("type of tx ", tx, typeof tx)
                        // console.log("transaction is open: ", tx.isOpen())
                        if (tx.isOpen()) {
                            if (query_result.length > 0) {
                                // console.log("~~transaction is open:  ", tx.isOpen())
                                for await (let result of query_result) {
                                    let causal_path = await result.get("cp").asRemote(tx)
                                    let attributes = await causal_path.getHas().collect()
                                    console.log("length of attributes: ", attributes.length)
                                    for await (let attribute of attributes) {
                                        // console.log("Attribute label type: ", attribute.type.label)
                                        if (attribute.type.label.name === "edge_strength") {
                                            attribute_value = attribute.value.split(":")
                                            // console.log("node id: ", effect_n)
                                            // console.log("attribute value: ", attribute_value)
                                            if (edge_strength[effect_n]) {
                                                edge_strength[effect_n] = { ...edge_strength[effect_n], [attribute_value[0]]: attribute_value[1] }
                                            } else {
                                                edge_strength[effect_n] = { [attribute_value[0]]: attribute_value[1] }
                                            }
                                        }
                                        if (attribute.type.label.name === "intrinsic_effects") {
                                            if (intrinsic_effects[effect_n]) {
                                                intrinsic_effects[effect_n].push(attribute.value)
                                            } else {
                                                intrinsic_effects[effect_n] = [attribute.value]
                                            }
                                        }
                                        if (attribute.type.label.name === "causal_mechanisms") {
                                            if (causal_mechanisms[effect_n]) {
                                                causal_mechanisms[effect_n].push(attribute.value)
                                            }
                                            else {
                                                causal_mechanisms[effect_n] = [attribute.value]
                                            }
                                        }
                                        if (attribute.type.label.name === "local_markov_test") {
                                            if (local_markov_test[effect_n]) {
                                                local_markov_test[effect_n].push(attribute.value)
                                            } else {
                                                local_markov_test[effect_n] = [attribute.value]
                                            }
                                        }
                                        if (attribute.type.label.name === "edge_dependence_test") {
                                            if (edge_dependence_test[effect_n]) {
                                                edge_dependence_test[effect_n].push(attribute.value)
                                            } else {
                                                edge_dependence_test[effect_n] = [attribute.value]
                                            }
                                        }
                                    }
                                }
                                await typedb.close_transaction(query_opts.transaction_type)
                            }
                        }
                    } else {
                        throw "No models deployed yet"
                    }
                    // } end of child wire iteration
                }
            }
        }
        return [edge_strength, intrinsic_effects, causal_mechanisms, local_markov_test, edge_dependence_test]
    } catch (exception) {
        console.log(`${_module} [getCausalStrengthEdges] throw exception`, exception)
        throw exception
    }
}

